# BFS from api_gateway must terminate (cycle safety)
# Grounding: Traversal from api_gateway with max_depth=5
def test_traversal_terminates_api_gateway(graph):
    """BFS from api_gateway must terminate within max_depth."""
    traverser = ImpactTraverser(graph, max_depth=5)
    result = traverser.traverse(["api_gateway"])
    # If we reach here, traversal terminated (no infinite loop)
    assert result is not None
    # All impacts must be within max_depth
    for imp in result.direct_impacts.values():
        assert imp.depth <= 5
    for imp in result.indirect_impacts.values():
        assert imp.depth <= 5


