# Graph must maintain bipartite structure
# Grounding: Edges only connect component nodes to module nodes
def test_bipartite_structure(graph):
    """Edges must only cross node types (component <-> module)."""
    for u, v in graph.graph.edges():
        u_type = graph.graph.nodes[u].get("node_type")
        v_type = graph.graph.nodes[v].get("node_type")
        assert u_type != v_type, (
            f"Edge {u} -> {v} connects same node types ({u_type})"
        )


# All edges must have coupling and usage metadata
# Grounding: Graph has 57 edges with metadata
def test_edge_metadata_present(graph):
    """Every edge must carry coupling and usage metadata."""
    for u, v, data in graph.graph.edges(data=True):
        assert "coupling" in data, (
            f"Edge {u} -> {v} missing coupling metadata"
        )
        assert data["coupling"] in ("tight", "loose", "optional"), (
            f"Edge {u} -> {v} has invalid coupling: {data['coupling']}"
        )

